// Checked before anything is written, so a missing plan or an archived template adds nothing.
(async () => {
  const refuse = (why) => { Outputs.why = why; Outputs.refuse(); };
  try {
    const R = Noodl.Records;
    const q = (c, where) => R.query(c, where, { limit: 2, plain: true });
    const planId = String(Inputs.planId || '');
    const templateId = String(Inputs.templateId || '');
    const plans = planId ? await q('Plan', { objectId: { equalTo: planId } }) : [];
    if (plans.length !== 1) return refuse('That plan is no longer there. Reload the page.');
    const templates = templateId ? await q('PlanTemplate', { objectId: { equalTo: templateId } }) : [];
    if (templates.length !== 1 || templates[0].archived === true) return refuse('That plan template is no longer offered. Reload the page and choose another.');
    const hasSteps = (await q('Step', { plan: { equalTo: planId } })).length > 0;
    if (!hasSteps) await R.save(planId, { title: templates[0].title, fromTemplate: templateId }, { className: 'Plan' });
    Outputs.job = { planId, learnerId: plans[0].learner, templateId };
  } catch (e) {
    console.error('[dbu:applyTemplate]', String((e && e.message) || e));
    Outputs.failed();
  }
})();
